create policy "access_participant_insert" on public.access_events for insert to authenticated with check(user_id=(select auth.uid()) and event_type in('check_in','check_out') and exists(select 1 from public.bookings b where b.id=booking_id and b.kitchen_id=access_events.kitchen_id and private.is_business_member(b.renter_business_id)));
create or replace function public.enforce_checkout_completion() returns trigger language plpgsql security invoker set search_path='' as $$ begin if new.event_type='check_out' and not exists(select 1 from public.booking_checklists bc where bc.booking_id=new.booking_id and bc.completed_by=new.user_id and bc.kind='post_use' and coalesce((bc.items->>'dishes_clean')::boolean,false) and coalesce((bc.items->>'equipment_off')::boolean,false) and coalesce((bc.items->>'lights_off')::boolean,false) and coalesce((bc.items->>'surfaces_sanitized')::boolean,false) and coalesce((bc.items->>'waste_removed')::boolean,false) and coalesce((bc.items->>'doors_secured')::boolean,false)) then raise exception 'Checkout checklist must be completed before check-out'; end if; return new; end; $$;
create trigger enforce_checkout_completion before insert on public.access_events for each row execute function public.enforce_checkout_completion();
create or replace function public.record_booking_access(p_booking_id uuid,p_event_type text,p_items jsonb default '{}'::jsonb,p_notes text default null) returns bigint language plpgsql security invoker set search_path='' as $$ declare v_user_id uuid:=auth.uid();v_kitchen_id uuid;v_event_id bigint;begin if v_user_id is null then raise exception 'Authentication required';end if;if p_event_type not in('check_in','check_out')then raise exception 'Invalid access event';end if;select b.kitchen_id into v_kitchen_id from public.bookings b where b.id=p_booking_id and private.is_business_member(b.renter_business_id);if v_kitchen_id is null then raise exception 'Booking not found or access denied';end if;if p_event_type='check_out' then if not(coalesce((p_items->>'dishes_clean')::boolean,false)and coalesce((p_items->>'equipment_off')::boolean,false)and coalesce((p_items->>'lights_off')::boolean,false)and coalesce((p_items->>'surfaces_sanitized')::boolean,false)and coalesce((p_items->>'waste_removed')::boolean,false)and coalesce((p_items->>'doors_secured')::boolean,false))then raise exception 'Every checkout confirmation is required';end if;insert into public.booking_checklists(booking_id,kind,completed_by,items,notes)values(p_booking_id,'post_use',v_user_id,p_items,nullif(trim(p_notes),''));end if;insert into public.access_events(kitchen_id,booking_id,user_id,event_type,details)values(v_kitchen_id,p_booking_id,v_user_id,p_event_type,jsonb_build_object('source','renter_app'))returning id into v_event_id;return v_event_id;end;$$;
revoke all on function public.record_booking_access(uuid,text,jsonb,text) from public,anon;grant execute on function public.record_booking_access(uuid,text,jsonb,text) to authenticated;revoke all on function public.enforce_checkout_completion() from public,anon,authenticated;
